{"content":"/**
 * Who is signed in and what may they do.
 *
 * Roles live in the database (user_roles) and can carry an expiry, which is
 * how temporary elevated permissions work. This hook is for UI affordances
 * only — the database enforces the real rules.
 */
import { useEffect, useState } from "react";
import type { User } from "@supabase/supabase-js";
import { supabase } from "@/integrations/supabase/client";

export type AppRole = "admin" | "sales" | "customer";

export interface RoleGrant {
  role: AppRole;
  expires_at: string | null;
}

export interface Access {
  user: User | null;
  roles: RoleGrant[];
  isAdmin: boolean;
  isSales: boolean;
  isStaff: boolean;
  /** Set when admin rights come from a time-limited grant. */
  adminExpiresAt: string | null;
  loading: boolean;
  reload: () => void;
}

export function useAccess(): Access {
  const [user, setUser] = useState<User | null>(null);
  const [roles, setRoles] = useState<RoleGrant[]>([]);
  const [loading, setLoading] = useState(true);
  const [nonce, setNonce] = useState(0);

  useEffect(() => {
    let cancelled = false;
    void (async () => {
      setLoading(true);
      const { data: userData } = await supabase.auth.getUser();
      if (cancelled) return;
      const current = userData.user ?? null;
      setUser(current);
      if (!current) {
        setRoles([]);
        setLoading(false);
        return;
      }
      const { data } = await supabase
        .from("user_roles")
        .select("role, expires_at")
        .eq("user_id", current.id);
      if (cancelled) return;
      const now = Date.now();
      setRoles(
        ((data ?? []) as RoleGrant[]).filter(
          (r) => !r.expires_at || new Date(r.expires_at).getTime() > now,
        ),
      );
      setLoading(false);
    })();
    return () => {
      cancelled = true;
    };
  }, [nonce]);

  useEffect(() => {
    const { data } = supabase.auth.onAuthStateChange((event) => {
      if (event === "SIGNED_IN" || event === "SIGNED_OUT" || event === "USER_UPDATED") {
        setNonce((n) => n + 1);
      }
    });
    return () => data.subscription.unsubscribe();
  }, []);

  const adminGrant = roles.find((r) => r.role === "admin");
  const isAdmin = Boolean(adminGrant);
  const isSales = roles.some((r) => r.role === "sales");

  return {
    user,
    roles,
    isAdmin,
    isSales,
    isStaff: isAdmin || isSales,
    adminExpiresAt: adminGrant?.expires_at ?? null,
    loading,
    reload: () => setNonce((n) => n + 1),
  };
}
